    impl<E: crate::capabilities::Render> Gfx<'_, E> {
        pub fn shape(
            &mut self,
            primitive: u32,
            vertices: &[GfxVertexData],
        ) -> Result<()> {
            self._engine.check()?;
            for input_item0 in (vertices).iter() {
                if ((input_item0).vertex).len() != 3 {
                    return Err(
                        crate::ApiError::new(crate::ErrorCode::InvalidArgument as i32),
                    );
                }
                if ((input_item0).normal).len() != 3 {
                    return Err(
                        crate::ApiError::new(crate::ErrorCode::InvalidArgument as i32),
                    );
                }
                if ((input_item0).tex_coord).len() != 2 {
                    return Err(
                        crate::ApiError::new(crate::ErrorCode::InvalidArgument as i32),
                    );
                }
                if ((input_item0).color).len() != 4 {
                    return Err(
                        crate::ApiError::new(crate::ErrorCode::InvalidArgument as i32),
                    );
                }
            }
            let result = {
                #[cfg(target_arch = "wasm32")]
                { spring::generated::owned::gfx::shape(primitive, vertices) }
                #[cfg(not(target_arch = "wasm32"))]
                { crate::native::gfx::shape(&self._engine, primitive, vertices) }
            };
            self._engine.finish(result)
        }
    }
